def coin_change(coins, amount):
    # Initialize the result list with a large number (since we can't have negative coins)
    results = [float('inf')] * (amount + 1)

    # Start from 0 because no coins are needed for amounts less than 0
    for i in range(1, amount + 1):
        if i % coins[0] == 0:
