    fac = {}

    # Iterate through all numbers from 2 to sqrt(n)
    for i in range(2, int(n**0.5)+1):
        if n % i == 0:
            j = n // i

            # Add both factors to the dictionary
            if i not in fac:
                fac[i] = 0

            fac[i] += 1

