def previous_palindrome(n):
    # Convert the number to a string
    num_str = str(n)

    # If there's no digit that forms a palindrome, return 0 (since there's no such number)
    if '0' not in num_str:
        return 0

    # Find the first character that appears twice consecutively
    for i in range(len(num_str) - 1):
        if num_str[i] == num_str[i + 1][::-1]:
            break

    else:
        # If no such character was found, return 0
        return 0

    # Remove the repeated character from the beginning of the string
    result = num_str[:i]

    # Return the resulting string as a new number
    return int(result)
