def left_insertion(arr, x):
    # Find the position where x would be inserted to maintain sorted order
    i = 0
    while i < len(arr) and arr[i] < x:
        i += 1

    # Shift elements of arr to make space for x
    for j in range(i, -1, -1):
        if arr[j-1] > x:
            arr.insert(j, x)
            break
    else:
        arr.append(x)

    return i
