def right_insertion(arr, x):
    # Find the correct position for x by iterating through the array
    for i in range(len(arr)):
        if arr[i] > x:
            # If current element is greater than or equal to x, insert it after finding its place
            arr.insert(i + 1, x)
            return i + 1
    # If all elements before x are smaller than x, insert x right after the last element
    arr.append(x)
    return len(arr)
