def removals(arr, m, k):
    # Sort the array
    arr.sort()

    # Calculate the maximum possible difference between the largest and second-largest elements
    max_diff = arr[-1] - arr[0]

    # If this difference is greater than k, return 0 as no removal is needed
    if max_diff > k:
        return 0

    # Calculate the minimum number of elements to remove
    for i in range(len(arr)):
        for j in range(i+1, len(arr)):
            if abs(arr[i] - arr[j]) <= k:
                return j - i

    return len(arr)
```

