def lcs_of_three(str1, str2, str3, l, m, n):
    # Initialize the matrix of lengths of longest common subsequences
    L = [[0] * (m + 1) for _ in range(l + 1)]

    # Fill the matrix
    for i in range(1, l+1):
        for j in range(1, m+1):
            if str1[i-1] == str2[j-1]:
                L[i][j] = L[i-1][j-1] + 1
            else:
                L[i][j] = max(L[i-1][j], L[i][j-1])

    # Find the maximum value in the last row and column
    max_lcs_length = L[l-1][m-1]

    # Return the index of the character that corresponds to this length
    return chr(max_lcs_length)
```

