```python
def maxAverageOfPath(matrix, r, c):
    # Initialize variables
    total_sum = float('inf')
    current_sum = 0

    # Iterate through all possible starting points (i, j)
    for i in range(r):
        for j in range(c):
            if i != 0:
                current_sum += matrix[i][j]
            elif j != 0:
                current_sum -= matrix[i][j]

    # If there's only one row or column left, return its value as the result
    if r == 1 or c == 1:
        return current_sum

    # Calculate the average for each possible path length from 2 to n^2-1
    for length in range(2, min(r, c)+1):
        current_sum = 0
        for x in range(r):
            for y in range(c):
                if x + length - 1 < r:
                    current_sum += matrix[x][y]
                else:
                    current_sum += matrix[x][(y+length)%c]

        avg = current_sum / (length*(r*c))
        if avg > total_sum:
            total_sum = avg

    return total_sum
```

