def sort_by_dnf(arr, n):
    # Initialize pointers for left and right sides of the array
    l = 0
    r = n - 1

    # Find the middle point where elements will be swapped if needed
    mid = (l + r) // 2

    while l < r:
        if arr[l] == 0:
            if arr[r] != 0:
                arr[l], arr[r] = arr[r], arr[l]
            else:
                r -= 1
        elif arr[l] == 1:
            if arr[r] != 1:
                arr[l], arr[r] = arr[r], arr[l]
            else:
                l += 1
        else:
            if arr[r] != 1:
                arr[l], arr[r] = arr[r], arr[l]
            r -= 1

        l += 1

    return arr
```

