def is_polite(n):
    def is_prime(num):
        if num <= 1:
            return False
        for i in range(2, int(num**0.5)+1):
            if num % i == 0:
                return False
        return True

    def is_pentagonal(num):
        p = (1 + (8 * num)**0.5) / 2
        return p.is_integer()

    def is_hexagonal(num):
        h = (num + 1) / 2
        return h.is_integer()

    if n < 1:
        return "Input must be a positive integer."

    i = 1
    while True:
        if is_prime(i) and is_pentagonal(i) and is_hexagonal(i):
            return i
        i += 1
```

