def lcm(a, b):
    # Calculate the greatest common divisor (GCD) using Euclidean algorithm
    def gcd(x, y):
        while(y):
            x, y = y, x % y

        return abs(x)

    # Calculate the least common multiple (LCM) using the formula LCM(a, b) = |a*b| / GCD(a, b)
    return abs(a*b) // gcd(a, b)
