def find_Min_Swaps(binary_array, n):
    # Initialize variables
    min_swaps = float('inf')

    # Iterate through all possible pairs of elements
    for i in range(n):
        for j in range(i + 1, n):
            # Swap if the current pair is not already sorted
            if binary_array[i] > binary_array[j]:
                # Calculate the number of swaps needed to sort the pair
                swaps = 0
                while i + swaps < n and binary_array[i + swaps] < binary_array[i]:
                    swaps += 1
                while j - swaps >= 0 and binary_array[j - swaps] > binary_array[j]:
                    swaps += 1
                # Update the minimum swaps found so far
                min_swaps = min(min_swaps, swaps)

    return min_swaps
```

