def coin_change(coins, amount, change=0):
    # If there are no coins left, return 0 if we haven't reached the target amount yet
    if not coins:
        return 0 if change < amount else float('inf')

    # Find the first coin that covers the remaining amount
    for i in range(len(coins)):
        if coins[i] <= amount:
            break
    else:
        return float('inf')

    # Subtract the cost of the chosen coin from the total amount
    amount -= coins[i]

    # Recur with the remaining possibilities
    return max(coin_change(coins[:i], amount, change+1), 
               coin_change(coins[i+1:], amount, change))
