def largest_subset(nums, k):
    # Sort the numbers based on their values
    nums.sort()

    # Initialize variables
    max_subset_size = 0
    current_subset = []

    for i in range(k):
        if len(current_subset) < i + 1:
            break
        if (i > 0) and (nums[i] == nums[i-1]):
            continue
        elif nums[i] % current_subset[-1] != 0:
            break
        else:
            current_subset.append(nums[i])

    # If no valid subset was found, return 0
    if not current_subset:
        return 0

    # Reconstruct the longest valid subset from the current subset
    for num in reversed(current_subset):
        if num <= nums[k-1]:
            del nums[k-1]
        else:
            nums.insert(k-1, num)

    # Return the length of the resulting subset
    return len(nums)
```

