    L = [[0] * (n + 1) for _ in range(l + 1)]

    # Fill the matrix
    for i in range(l + 1):
        for j in range(n + 1):
            if i == 0 or j == 0:
                L[i][j] = 0

            elif str1[i - 1] == str2[j - 1]:
                L[i][j] = L[i - 1][j - 1] + 1

