        if k not in freq_s2 or freq_s2[k] != v:
            diff_chars.append(k)

    # If there are more than 1 differing character, it's impossible to make them equal
    if len(diff_chars) > 1:
        return "Not Possible"

    # Calculate the number of swaps needed
    i = 0
    for c in diff_chars:
        j = freq_s2[c] - freq_s1[c]
        i += abs(j)

