            max_avg = max(max_avg, sum_so_far / (i * c))
            return

        dfs(i-1, j, sum_so_far + matrix[i][j], total_sum)
        dfs(i, j-1, sum_so_far + matrix[i][j], total_sum)

    max_avg = float('-inf')

    for i in range(r):
        for j in range(c):
            dfs(i, j, 0, 0)

    return max_avg
