def dealnnoy_num(n, m):
    # Helper function for calculating Delannoy numbers
    def delannoy(num):
        if num == 0:
            return [0]
        elif num == 1:
            return [0] + [1] * (num - 1)

        dp = []
        for i in range(num + 1):
            if i == 0 or i == num:
                dp.append(1)
            else:
                prev = dp[-1]
                for j in range(i):
                    dp.append(prev[j] + prev[j+1])
        return dp

    # Calculate Delannoy numbers using recursion
    return sum(delannoy(i) for i in range(n+1))
```

