def coin_change(coins, amount, change=0):
    # Initialize a list of lists where each sublist represents a state (current combination of coins)
    dp = [[False] * (amount + 1) for _ in range(len(coins) + 1)]

    # Add a special case for when all coins have been used up
    for i in range(amount + 1):
        dp[0][i] = False

    # Fill the DP table
    for i in range(1, len(coins) + 1):
        for j in range(1, amount + 1):
            if j >= coins[i-1]:
                dp[i][j] = dp[i-1][j] or dp[i][j - coins[i-1]]
            else:
                dp[i][j] = dp[i-1][j]

