def largest_subset(nums, k):
    # Sort the numbers by their value
    sorted_nums = sorted(nums)

    def dfs(index, path, end):
        if len(path) == k:
            yield path[:]

        for i in range(index, len(sorted_nums)):
            if i > index and sorted_nums[i] == sorted_nums[i-1]:
                continue

            new_path = list(path)
            new_path.append(sorted_nums[i])

            if i >= end:
                yield from dfs(i+1, new_path, end)
            else:
                dfs(i+1, new_path, i+1)

    return next(dfs(0, [], len(sorted_nums)), [])
