    dp = [[0] * (m + 1) for _ in range(m + 1)]

    # Fill the first row and column of the DP table
    for i in range(m + 1):
        dp[i][0] = i

    for j in range(m + 1):
        dp[0][j] = j

    # Fill the rest of the DP table
    for i in range(1, m + 1):
        for j in range(1, m + 1):
            if i == j:
                dp[i][j] = 1
            elif i > j:
                dp[i][j] = dp[i - 1][j]
            else:
                dp[i][j] = dp[i][j - 1] + dp[i - 1][j]

    return dp[m][m]
```

