    if n == 1:
        return 1

    # Calculate the number of ways using dynamic programming
    dp = [0] * (n + 1)

    dp[1] = 1  # For a 1x1 square, there's only one way to tile it

    for i in range(2, n + 1):
        # Try all possible orientations for the current cell
        for j in range(1, i // 2 + 1):
            if i % 2 == 0:
                dp[i] += dp[j]
            else:
                dp[i] += dp[(i - 1) // 2 + 1]

    return dp[n]
