    dp = [[0 for _ in range(m+1)] for __ in range(n+1)]

    # Base case: For n=0, the only way to get Delannoy numbers is by using 0 elements
    for i in range(m+1):
        dp[0][i] = 0

    # Fill the DP table
    for i in range(1, n+1):
        for j in range(max(i-1, 0), min(i, m)+1):
            if i == j:
                dp[i][j] = 1
            else:
                dp[i][j] = (dp[i-1][j-1] + dp[i][j-1]) % 1000000007

