def last_Two_Digits(n):
    # Calculate factorials up to n using recursion or iteration
    def factorial(num):
        if num == 0 or num == 1:
            return 1
        else:
            return num * factorial(num - 1)

    # Get the last two digits by taking modulo 100 of each factorial result
    last_two_digits = [factorial(i) % 100 for i in range(1, n + 1)]

    return last_two_digits[-1]  # Return the last element of the list (since we're interested in the last two digits)
