def subset(arr, n):
    # Initialize result as a dictionary for storing counts of subsets
    res = {}

    def backtrack(start, path):
        if len(path) == n:
            return 1

        count = 0
        for i in range(start, n):
            if (i not in path) and (arr[i] not in set(path + [arr[i]])):
                count += backtrack(i+1, path + [arr[i]])

        res[path] = count

    backtrack(0, [])
    return min(res.values())
```

