def subset(arr, n):
    # Initialize dp array where dp[i] will store the minimum number of subsets
    # whose sum is i
    dp = [float('inf')] * (n + 1)

    # Fill dp array from 0 to n
    for i in range(n + 1):
        min_count = float('inf')

        for j in range(i, -1, -1):
            if j > i:
                break

            if arr[j - 1] <= i:
                count = i - j + 1

                if count < min_count:
                    min_count = count

        dp[i] = min_count

    return dp[n]
```

