def find_Min_Swaps(binary_array, n):
    # Initialize variables
    min_swaps = float('inf')

    # Iterate through all possible pairs of adjacent elements
    for i in range(n):
        for j in range(i+1, n):
            if binary_array[i] != binary_array[j]:
                # Calculate the number of swaps needed to make them equal
                swaps = 0
                while binary_array[i] != '0' or binary_array[j] != '1':
                    if binary_array[i] == '0':
                        i += 1
                    else:
                        j -= 1
                    swaps += 1
                min_swaps = min(min_swaps, swaps)

    return min_swaps
```

