def min_Swaps(str1, str2):
    # Calculate the difference between the two strings
    diff = abs(len(str1) - len(str2))

    # If the lengths differ by more than one bit, no swaps are needed
    if diff > 1:
        return 0

    # Swap characters until there's a mismatch
    for i in range(diff):
        if str1[i] != str2[i]:
            str1, str2 = str2[:i] + str2[i+1:], str1

    return len(str1)
