def min_Swaps(str1, str2):
    # Calculate the difference between the lengths of the two strings
    diff_len = len(str1) - len(str2)

    # If the length of str1 is greater than str2, swap them
    if str1 > str2:
        return diff_len

    # Otherwise, swap characters until they are equal
    for i in range(diff_len):
        if str1[i] != str2[i]:
            str1 += str2[:i] + str2[i+1:]
            break
    else:
        return 0

    return len(str1)
```

