    bracket_map = {'(': ')', '{': '}', '[': ']'}

    # List to use as stack for closing brackets
    stack = []

    # Iterate through each character in the expression
    for char in expression:
        if char in bracket_map:
            # If it's an open bracket, push it onto the stack
            stack.append(char)
        elif len(stack) > 0:
            # If there's a close bracket without a corresponding open one,
            # return false
            if bracket_map[stack[-1]] != char:
                return False
        else:
            # If any close bracket without a corresponding open one,
            # return false
            return False

    # If there's anything left in the stack, it's unbalanced
    return len(stack) == 0
