def get_Pairs_Count(arr, n, k):
    # Counting sort for sorting elements in ascending order
    count = [0] * (max(arr) + 1)

    for i in arr:
        count[i] += 1

    # Creating a new list from counts
    sorted_arr = [i for i in range(n)]

    # Replacing old indices with values from sorted array
    i = 0
    for j in range(len(sorted_arr)):
        if sorted_arr[j] != i:
            sorted_arr[j] = count[sorted_arr[j]]

    # Finding all pairs that add up to 'k'
    count = 0
    for i in range(n):
        for j in range(i+1, n):
            if (sorted_arr[i] + sorted_arr[j]) == k:
                count += 1

    return count
```

