def find_Points(start1, end1, start2, end2):
    # Initialize variables
    intersection_start = float('inf')
    intersection_end = float('-inf')

    # Iterate through all possible combinations of starting points from start1 to end1
    for i in range(start1, end1 + 1):
        if i < start2 or i > end2:
            continue

        # Check if the current pair of points intersects any other pair
        if (i - start1 >= 0 and i - start2 >= 0) or (i - start1 < 0 and i - end2 >= 0):
            intersection_start = min(intersection_start, i)
            intersection_end = max(intersection_end, i)

    return (intersection_start, intersection_end)
```

