def count_Rotation(arr, n):
    # Find the index where swapping would sort the array
    i = 0
    while i < n - 1:
        if arr[i] > arr[i + 1]:
            arr[i], arr[i + 1] = arr[i + 1], arr[i]
        else:
            i += 1
        j = i + 1
        while j < n and arr[j] <= arr[i]:
            j += 1
        arr[i], arr[j - 1] = arr[j - 1], arr[i]

    return i
```

