def count_Rotation(arr, n):
    # Find the rightmost increasing element
    i = j = n - 1

    while i > -1:
        if arr[i] < arr[j]:
            i += 1
        else:
            break

    if i == -1:
        return 0

    # Find the position where elements after it become non-increasing
    for k in range(i + 1, n):
        if arr[k] > arr[k - 1]:
            continue
        else:
            return k

    return n
