def min_Jumps(x, y, d):
    # Initialize variables
    max_jumps = 0

    # Iterate until you reach the end of either x or y
    while x > 0 or y > 0:
        if x == 0:
            return float('inf')

        max_jumps += 1

        # If reaching y becomes impossible, return -1
        if y == 0:
            return -1

        # Move towards the nearest unvisited spot that's at least 'd' distance away from current position
        if x >= y:
            x -= d
        else:
            y -= d

    return max_jumps
