def min_Joins(x, y, z):
    # If any jump exceeds 1 unit, return infinity
    if max(z - x, y - z) > 1:
        return float('inf')

    # Initialize the maximum number of jumps as 0
    max_jumps = 0

    # Iterate until we can't move anymore
    while True:
        if x == y and z == 0:
            break

        # Move towards the point (x, 0)
        x += 1
        if x >= z:
            x = z

        elif y >= z:
            y -= 1

        # Update the maximum number of jumps
        max_jumps += 1

    return max_jumps
```

