def is_Isomorphic(s, t):
    # Dictionary to store characters of s as keys and their indices as values
    s_map = {}

    # Dictionary to store characters of t as values and their indices as keys
    t_map = {}

    # Iterate through each character in string s
    for i in range(len(s)):
        # Check if character is already present in s_map
        if (s[i] in s_map) and (s_map[s[i]] != i):
            return False

        # Check if character is also present in t_map
        if (t[i] in t_map) and (t_map[t[i]] != i):
            return False

        # Store characters in respective dictionaries
        s_map[s[i]] = i
        t_map[t[i]] = i

    # If no contradictions were found, strings are isomorphic
    return True
```

