def largest_subset(nums, k):
    # Sort nums by their values in descending order
    sorted_nums = sorted(nums, key=lambda x: x[-1], reverse=True)

    def can_form_subset(subset, remaining):
        if len(subset) == k:
            return True
        for num in subset:
            if (num[0] - num[1]) <= remaining < num[0]:
                if not can_form_subset([num] + subset, remaining - (num[0] - num[1])):
                    return False
        return True

    min_diff = float('inf')
    max_subset = []

    for i in range(len(sorted_nums)):
        for j in range(i+1, len(sorted_nums)+1):
            current_set = sorted_nums[:i] + sorted_nums[j:]

            if can_form_subset(current_set, k-1):
                diff = abs(sorted_nums[i][0]-sorted_nums[i][1])

                if diff < min_diff:
                    min_diff = diff
                    max_subset = [sorted_nums[i]]
                elif diff == min_diff:
                    max_subset.append(sorted_nums[i])

    return max_subset
```

