def largest_subset(numbers, n):
    # Sort numbers by their value-to-index ratio starting from 0
    sorted_indices = sorted([(num[i], i) for i in range(len(numbers))])

    def can_form_subset(subset, remaining):
        if not remaining:
            return True

        count = 0
        for index, num in enumerate(subset):
            if num % remaining[index] != 0:
                return False
            count += 1

        return count == len(subset)

    max_subset_size = 0
    best_subset = []

    for i in range(n):
        subset = [numbers[j] for j in sorted_indices[:i+1]]

        if all(can_form_subset(subset, remaining) for remaining in (sorted_indices[i+1:],)):
            if len(subset) > max_subset_size:
                max_subset_size = len(subset)
                best_subset = subset

    return best_subset
