def largest_subset(nums, k):
    # Sort nums by their value-to-index pairs
    sorted_nums = sorted(zip(nums, range(len(nums))))

    def can_form_subset(index, current_subset):
        if len(current_subset) > k:
            return False
        for i in range(k):
            if not (current_subset[i] % nums[i]) or index[i] != i:
                break
        else:
            return True

        for j in range(i + 1, k):
            if not (nums[j] % current_subset[-1]) == 0:
                return False

        return True

    left, right = 0, 0
    while right < len(sorted_nums):
        if can_form_subset(left, sorted_nums[left]):
            right += 1
        left += 1

    return right
```

