def check_min_heap(arr, n):
    # Base case: empty array or single element array is a valid min-heap
    if n <= 1:
        return True

    # Traverse through all elements except the last one
    for i in range(n // 2 - 1, -1, -1):
        if arr[i] > arr[2 * i + 1]:
            return False

    return True
