def count_vowels(s):
    # Initialize a counter for vowels found consecutively
    vowel_count = 0

    # Iterate through each character in the string
    for i in range(len(s)):
        if s[i] in 'aeiouAEIOU':
            # If a vowel is found at any position before the current one, increment the counter
            if i > 0:
                vowel_count += 1

            # Skip non-alphabetic characters after the current one
            while i < len(s) - 1 and not s[i+1].isalpha():
                i += 1

    return vowel_count
