def min_Swaps(a, b):
    # Calculate the difference between the lengths of a and b
    diff_len = len(a) - len(b)

    # If the length of a is longer than b, swap their lengths
    if diff_len > 0:
        a, b = b, a

    # Find the first position where a[i] does not match b[i]
    for i in range(len(a)):
        if a[i] != b[i]:
            return "Not Possible"

    # Return the count of swaps needed
    return int((len(a) + diff_len) / 2)
```

