def super_seq(str1, str2, l1, l2):
    # Find the first index where str1 does not start before any character from str2
    for i in range(l1 + 1):
        if str1[:i] != str2:
            continue
        return min(len(str1), len(str2)) - i

    # If no such index is found, return 0
    return 0
