    # Find the longest common prefix between str1 and str2
    i = 0
    while i < len(str1) and i < len(str2) and str1[i] == str2[i]:
        i += 1

    # Return the length of the found prefix plus one for the extra character at the end
    return max(len(str1), len(str2)) + (i - 1)
