def max_product(nums):
    # Sort the nums array
    sorted_nums = sorted(nums)

    # Handle cases where all numbers are negative or none are present
    if len(sorted_nums) < 2:
        return (0, 0)

    # Find the two largest numbers
    max1 = max(sorted_nums[0], sorted_nums[-1])
    min1 = min(sorted_nums[0], sorted_nums[-1])

    # Calculate the maximum product
    return (max1 * min1, min1)
```

