from heapq import heappush, heappop
def nth_super_ugly_number(n, nums):
    # Initialize the heap with the first three elements from the given list
    heap = nums[:3]

    # Generate the next super ugly numbers by multiplying them together
    while len(heap) < n:
        current = heappop(heap)
        if current % 2 == 0:
            heappush(heap, current * 2)
        if current % 3 == 0:
            heappush(heap, current * 3)
        if current % 7 == 0:
            heappush(heap, current * 7)

    return heappop(heap)
```

