def num_position(s):
    # Split the string into words
    words = s.split()

    # Create a dictionary to hold the count of each word's position
    positions = {}

    for i, word in enumerate(words):
        if word in positions:
            positions[word] += [i]
        else:
            positions[word] = [i]

    # Print the results
    for word, positions_in_sentence in sorted(positions.items()):
        print(f"'{word}': [{', '.join(map(str, positions_in_sentence))}]")
