def num_position(s):
    # Split the string into words
    words = s.split()

    # Initialize variables
    count = 0
    index = 0

    # Iterate through each word's characters
    for char in words:
        if char.isdigit():
            count += 1
        else:
            # If a non-digit character is found after digit group,
            # add its position to the result list
            if index != len(words) - 1:
                index += 1
            else:
                break

    return (count, index)
```

