def get_median(arr1, arr2, n):
    # Initialize pointers for both arrays
    i = j = 0

    # Loop until we have processed all elements
    while i < n // 2 and j < len(arr2):
        if arr1[i] < arr2[j]:
            arr1[i], arr2[j] = arr2[j], arr1[i]
            i += 1
        j += 1

    # If there's an extra element in one array, place it at the end
    if i < n:
        arr1.extend(arr2[i:])

    # Calculate the median
    m = len(arr1)
    if m % 2 == 0:
        return (arr1[m//2 - 1] + arr1[m//2]) / 2.0
    else:
        return arr1[m//2]
```

