def lcs_of_three(str1, str2, str3, l, m, n):
    # Initialize the matrix for dynamic programming
    dp = [[0] * (m+1) for _ in range(l+1)]

    # Fill the matrix
    for i in range(1, l+1):
        for j in range(1, m+1):
            if str1[i-1] == str2[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])

    # Find the maximum value in the last row and column
    max_val = max([dp[l-i][c-j] for i in range(l) for c in range(c+1)])

    return max_val
```

