    L = [[0] * (l + 1) for i in range(n + 1)]

    # Fill the matrix
    for i in range(1, n+1):
        for j in range(1, l+1):
            if s1[i-1] == s2[j-1]:
                L[i][j] = L[i-1][j-1] + 1
