def find_triplet_array(arr, target_sum, other_target):
    # Sort the array
    arr.sort()

    # Iterate through all possible pairs of elements
    for i in range(len(arr)-1):
        j = i + 1

        # Avoiding duplicates by checking if j is not at the same index as i
        while j < len(arr):
            current_sum = arr[i] + arr[j]

            # If the current sum equals the target sum, return the indices
            if current_sum == target_sum:
                return (i, j, arr[j])

            # Move j forward if the sum is less than the target
            elif current_sum < target_sum:
                j += 1

            # Move i forward if the sum is greater than the target
            else:
                i += 1

    return None
