def heapify(arr, n, i):
    # Find largest element in left sub-tree
    largest = i

    for j in range(i+1, n):
        if arr[j] > arr[largest]:
            largest = j

    # Swap if needed
    if largest != i:
        arr[i], arr[largest] = arr[largest], arr[i]

    # Heapify the affected sub-tree
    heap_size = n - 1 - i
    while (i * 2) < heap_size:
        mn = i * 2
        if (mn + 1) <= heap_size and arr[mn] < arr[mn + 1]:
            mn += 1

        if arr[i] < arr[mn]:
            arr[i], arr[mn] = arr[mn], arr[i]

        i = mn
```

