def maxAverageOfPath(matrix, k):
    def dfs(row, col, path_sum, current_k):
        if row < 0 or col < 0 or row >= len(matrix) or col >= len(matrix[0]) or (row, col) in visited:
            return None

        visited.add((row, col))

        total_sum = path_sum + matrix[row][col]
        if current_k == 0:
            result = max(total_sum, result)
        else:
            new_path_sum = total_sum / (k - 1)

            # Recursively find the new maximum average
            next_result = maxAverageOfPath(matrix, current_k - 1, new_path_sum, k)
            if next_result is not None:
                result = max(result, next_result)

        # Backtrack by removing the current cell from the visited set
        visited.remove((row, col))

        return new_path_sum

    result = float('-inf')

    for i in range(len(matrix)):
        for j in range(len(matrix[i])):
            if (i, j) not in visited:
                temp_result = dfs(i, j, 0, k)

                if temp_result is not None:
                    result = max(result, temp_result)

    return result
