        return maxAverageOfPath(matrix[r:], r - 1, c)

    total_sum = float('inf')
    current_path = {}

    for i in range(r):
        row_sum = sum(matrix[i][j] for j in range(c))
        total_sum = min(total_sum, row_sum)

        previous_row_sum = None
        for key, value in current_path.items():
            if key != 'previous':
                new_sum = (key[0] + 1) * key[1] + value['sum'] + (value.get('cost', 0) or 0)
                if new_sum < previous_row_sum:
                    previous_row_sum = new_sum

        if previous_row_sum == None or (total_sum - previous_row_sum) / c == 0:
            return 0

        current_path.update({'previous': {}})
        current_path['current'] = {'sum': row_sum, 'cost': total_sum}

    return current_path['current']['sum']
