def maxAverageOfPath(matrix, k):
    def calculate_average(row, col):
        total = 0
        for i in range(col):
            total += matrix[row][i]
        return total / (col - 1)

    if k > len(matrix):
        raise ValueError("Invalid value for 'k'")

    # Initialize the dp array where dp[i][j] represents the maximum average up to index (i, j)
    dp = [[[0 for _ in range(len(matrix[0]))] for _ in range(k)] for _ in range(len(matrix))]

    # Fill the dp table
    for i in range(len(matrix)):
        for j in range(k):
            prev_max = float('-inf')
            for x in range(max(0, i-k), min(i+1, len(matrix))):
                curr_avg = calculate_average((i, x), (i, j))
                prev_max = max(prev_max, curr_avg)

            dp[i][j][0] = prev_max

    # Find the maximum average across all valid paths
    max_average = float('-inf')
    for i in range(len(matrix)):
        for j in range(k):
            max_average = max(max_average, dp[i][j][1])

    return max_average
