def max_chain_length(pairs, n):
    # Initialize variables
    max_length = 0
    current_length = 1

    for i in range(n-1):
        if pairs[i].start > pairs[i+1].end:
            continue
        elif pairs[i].end > pairs[i+1].start:
            # Found a new longer chain starting at this pair
            if current_length > (i + 1):
                current_length = i + 1
            else:
                # Update the maximum length found so far
                max_length = max(max_length, current_length)

        # Move to the next pair
        current_length += 1

