def min_jumps(nums, k):
    # Initialize variables
    jump_lengths = [float('inf')] * len(nums)
    jump_lengths[0] = 0

    # Fill up the jump_lengths array
    for i in range(1, len(nums)):
        for j in range(i):
            if nums[j] >= i - j && (jump_lengths[i] == float('inf') || jump_lengths[i] > jump_lengths[j] + 1):
                jump_lengths[i] = jump_lengths[j] + 1

    # Find the minimum number of jumps needed to reach or exceed the last index
    min_jumps = float('inf')
    for i in range(k, -1, -1):
        if i != 0:
            min_jumps = min(min_jumps, jump_lengths[i-1])

    return min_jumps
