def min_jumps(nums, n):
    # Initialize variables
    max_steps = 0
    current_step = 0

    # Iterate through all possible pairs of consecutive elements
    for i in range(n - 1):
        if i + nums[i] >= n:
            break

        # Update max_steps if current step is less than max_steps
        max_steps = max(max_steps, i + nums[i])

        # If we've reached the end, return max_steps as it's the answer
        if i + nums[i] == n - 1:
            return max_steps

        # Jump to the next index that is at most `max_steps` steps ahead
        j = i + 1
        while j <= i + nums[i]:
            if j < n:
                if j - i + 1 > max_steps:
                    max_steps = j - i + 1
            j += 1

    return max_steps
```

