def min_jumps(nums, n):
    # Initialize variables
    dp = [float('inf')] * n
    dp[0] = 0

    for i in range(n):
        for j in range(i + 1 <= n - 1):
            if (i + nums[i]) >= n:
                break

            if i != 0 and dp[j] == float('inf'):
                continue

            dp[j] = min(dp[j], dp[i] + 1)

    return dp[n-1]
