def generate_matrix(n):
    def spiral_traversal(row_start, col_start, row_end, col_end):
        for i in range(col_start, col_end + 1):
            print(f"({row_start}, {i})")

        for i in range(row_start, row_end):
            print(f"({i}, {col_end}))")

        if row_start != row_end:
            for i in range(col_end - 1, col_start - 1, -1):
                print(f"({row_end}, {i})")

        if col_start != col_end:
            for i in range(row_end - 1, row_start, -1):
                print(f"({i}, {col_start})")

    # Initialize the result matrix with zeros
    matrix = [[0] * n for _ in range(n)]

    # Start from the top-left corner (1, 1) and follow the spiral pattern
    x, y = 0, 0

    # Iterate until all elements are placed
    while x <= n - 1 and y <= n - 1:
        # Place the current number in its correct position
        matrix[x][y] = n * (x + y + 1)

        # Move right
        x += 1

        # If out of bounds, move left
        if x > n - 1 or matrix[x-1][y] != 0:
            y += 1

    return matrix
```

