def pack_consecutive_duplicates(arr):
    result = []
    current_group = []

    for i in range(len(arr)):
        if i == 0 or arr[i] != arr[i-1]:
            result.append(current_group)
            current_group = [arr[i]]
        else:
            current_group.append(arr[i])

    # Add the last group if it's not empty
    if current_group:
        result.append(current_group)

    return result
