import re
def extract_date(url):
    # Extracting year from URL
    match = re.search(r'\d{4}', url)
    if match:
        year = match.group()
    else:
        return None

    # Extracting month from URL
    match = re.search(r'(\d{1,2})/', url)
    if match:
        month = match.group(1)
    else:
        return None

    # Extracting day from URL
    match = re.search(r'(\d{1,2}/\d{1,2}/\d{4})', url)
    if match:
        day = match.group(1)
    else:
        return None

    return [year, month, day]
```

