import re
def extract_date(url):
    # Extract year from the URL
    match = re.search(r'(\d{4})/', url)

    if match:
        year = match.group(1)

        # Extract month from the extracted year
        month_match = re.search(r'\d{1,2}/\d{1,2}', year)
        if month_match:
            month = month_match.group(0)[2:]
        else:
            month = "01"

        # Extract day from the month
        day_match = re.search(r'\d{1,2}/\d{1,2}', year)
        if day_match:
            day = day_match.group(0)[2:]
        else:
            day = "01"

        return [year, month, day]
    else:
        return []
```

